/**
 * Loads the caller's workspace membership, then renders an invite
 * form (owner/admin only), the member list, and pending invitations.
 * A "member" role gets a read-only view: no invite form, no pending
 * invitations, no role/remove controls. Only an owner can make another
 * member an owner; every role can leave.
 */

import { getTranslations } from "next-intl/server";

import { requireWorkspace } from "@intelligo-dev/auth";

import { team } from "@/lib/team";
import { InviteMemberForm } from "@/components/team/invite-member-form";
import { LeaveWorkspace } from "@/components/team/leave-workspace";
import { MemberList } from "@/components/team/member-list";
import { PendingInvitations } from "@/components/team/pending-invitations";
import {
  PageHeader,
  PageHeaderContent,
  PageHeaderDescription,
  PageHeaderTitle,
} from "@/components/ui/page-header";

export default async function TeamSettingsPage() {
  const t = await getTranslations("team-settings");
  const { user, workspace, membership } = await requireWorkspace();
  const canManage = ["owner", "admin"].includes(membership.role);

  const [members, allInvitations] = await Promise.all([
    team.listMembers(),
    canManage ? team.listInvitations() : Promise.resolve([]),
  ]);
  // The organization keeps accepted, rejected and canceled invitations too.
  const invitations = allInvitations.filter(
    (invitation) => invitation.status === "pending"
  );

  return (
    <div className="space-y-8">
      <PageHeader>
        <PageHeaderContent>
          <PageHeaderTitle level={2}>{t("page.title")}</PageHeaderTitle>
          <PageHeaderDescription>
            {canManage
              ? t("page.descriptionManage", { workspace: workspace.name })
              : t("page.descriptionReadOnly", { workspace: workspace.name })}
          </PageHeaderDescription>
        </PageHeaderContent>
      </PageHeader>

      {canManage && <InviteMemberForm />}

      <MemberList
        members={members}
        currentUserId={user.id}
        canManage={canManage}
        canTransfer={membership.role === "owner"}
      />

      {canManage && <PendingInvitations invitations={invitations} />}

      <section className="border-t pt-8">
        <LeaveWorkspace workspaceName={workspace.name} />
      </section>
    </div>
  );
}

"use client";

/**
 * Member list — table of workspace members with role changes and
 * removal. Owner/admin only for the management controls; anyone else
 * sees a read-only table. An owner can also make another member an
 * owner, behind a confirmation.
 */

import { useState, useTransition } from "react";
import { useFormatter, useTranslations } from "next-intl";
import { toast } from "sonner";

import type { OrgMember } from "@intelligo-dev/auth";

import {
  removeMember,
  transferOwnership,
  updateMemberRole,
} from "@/actions/team";
import { RoleBadge } from "./role-badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";

/**
 * `getFullOrganization()` returns a richer member record than the
 * `OrgMember` type declared in `@intelligo-dev/auth` (documented there as
 * the "minimal" shape: `id`, `userId`, `role`) — Better-Auth also
 * joins the `user` record and a `createdAt` timestamp onto each
 * member. Both are declared optional here so the table still renders
 * (falling back to the member id) if a future version omits them.
 */
export type TeamMember = OrgMember & {
  user?: { name?: string | null; email?: string | null } | null;
  createdAt?: string | Date;
};

interface MemberListProps {
  members: TeamMember[];
  currentUserId: string;
  canManage: boolean;
  /** Owners only: shows "Make owner" on every other non-owner member. */
  canTransfer?: boolean;
}

export function MemberList({
  members,
  currentUserId,
  canManage,
  canTransfer = false,
}: MemberListProps) {
  const t = useTranslations("team-settings");
  // The labels SelectValue shows; Base UI renders the raw value without them.
  const roleItems = [
    { value: "member", label: t("roles.member") },
    { value: "admin", label: t("roles.admin") },
  ];
  const format = useFormatter();
  const [isPending, startTransition] = useTransition();
  const [busyId, setBusyId] = useState<string | null>(null);
  // The target outlives `transferOpen` so the name stays while the dialog exits.
  const [transferTarget, setTransferTarget] = useState<{
    id: string;
    name: string;
  } | null>(null);
  const [transferOpen, setTransferOpen] = useState(false);
  const isTransferring =
    isPending && transferTarget !== null && busyId === transferTarget.id;

  function handleRoleChange(memberId: string, role: string) {
    setBusyId(memberId);
    startTransition(async () => {
      const result = await updateMemberRole({
        memberId,
        role: role as "admin" | "member",
      });
      if (!result.success) {
        toast.error(result.error);
      } else {
        toast.success(t("memberList.roleUpdated"));
      }
      setBusyId(null);
    });
  }

  function handleRemove(memberId: string, name: string) {
    setBusyId(memberId);
    startTransition(async () => {
      const result = await removeMember(memberId);
      if (!result.success) {
        toast.error(result.error);
      } else {
        toast.success(t("memberList.memberRemoved", { name }));
      }
      setBusyId(null);
    });
  }

  function handleTransfer() {
    if (!transferTarget) return;
    const { id, name } = transferTarget;
    setBusyId(id);
    startTransition(async () => {
      const result = await transferOwnership(id);
      if (!result.success) {
        toast.error(result.error);
      } else {
        toast.success(t("memberList.ownershipTransferred", { name }));
      }
      setBusyId(null);
      setTransferOpen(false);
    });
  }

  return (
    <div>
      <h2 className="mb-3 text-sm font-semibold">
        {t("memberList.heading", { count: members.length })}
      </h2>

      {members.length === 0 ? (
        <div className="rounded-md border border-dashed px-6 py-10 text-center">
          <p className="text-sm font-medium">{t("memberList.empty")}</p>
          <p className="mt-1 text-sm text-muted-foreground">
            {t("memberList.emptyHint")}
          </p>
        </div>
      ) : (
        <div className="rounded-md border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>{t("memberList.columns.name")}</TableHead>
                <TableHead className="hidden md:table-cell">
                  {t("memberList.columns.email")}
                </TableHead>
                <TableHead>{t("memberList.columns.role")}</TableHead>
                <TableHead className="hidden md:table-cell">
                  {t("memberList.columns.joined")}
                </TableHead>
                {canManage && (
                  <TableHead className="text-right">
                    {t("memberList.columns.actions")}
                  </TableHead>
                )}
              </TableRow>
            </TableHeader>
            <TableBody>
              {members.map((member) => {
                const memberId = member.id ?? member.userId;
                const isCurrentUser = member.userId === currentUserId;
                const isOwner = member.role === "owner";
                const isBusy = isPending && busyId === memberId;
                const name = member.user?.name || member.userId;

                return (
                  <TableRow key={memberId}>
                    <TableCell className="font-medium">
                      {name}
                      {isCurrentUser && (
                        <span className="ml-2 text-xs text-muted-foreground">
                          {t("memberList.you")}
                        </span>
                      )}
                      {/* The email column is hidden on small screens,
                          so the primary cell carries it there. */}
                      <span className="block truncate text-xs font-normal text-muted-foreground md:hidden">
                        {member.user?.email ?? "—"}
                      </span>
                    </TableCell>
                    <TableCell className="hidden md:table-cell">
                      {member.user?.email ?? "—"}
                    </TableCell>
                    <TableCell>
                      {canManage && !isOwner && !isCurrentUser ? (
                        <Select
                          value={member.role}
                          items={roleItems}
                          onValueChange={(value) =>
                            value && handleRoleChange(memberId, value)
                          }
                          disabled={isBusy}
                        >
                          <SelectTrigger className="w-32">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="member">
                              {t("roles.member")}
                            </SelectItem>
                            <SelectItem value="admin">
                              {t("roles.admin")}
                            </SelectItem>
                          </SelectContent>
                        </Select>
                      ) : (
                        <RoleBadge role={member.role} />
                      )}
                    </TableCell>
                    <TableCell className="hidden md:table-cell">
                      {member.createdAt
                        ? format.dateTime(new Date(member.createdAt), {
                            dateStyle: "medium",
                          })
                        : "—"}
                    </TableCell>
                    {canManage && (
                      <TableCell className="text-right">
                        {canTransfer && !isOwner && !isCurrentUser && (
                          <Button
                            variant="ghost"
                            size="sm"
                            disabled={isBusy}
                            onClick={() => {
                              setTransferTarget({ id: memberId, name });
                              setTransferOpen(true);
                            }}
                          >
                            {t("memberList.transferDialog.trigger")}
                          </Button>
                        )}
                        {!isCurrentUser && !isOwner && (
                          <Dialog>
                            <DialogTrigger
                              render={
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  disabled={isBusy}
                                />
                              }
                            >
                              {t("memberList.removeDialog.trigger")}
                            </DialogTrigger>
                            <DialogContent>
                              <DialogHeader>
                                <DialogTitle>
                                  {t("memberList.removeDialog.title")}
                                </DialogTitle>
                                <DialogDescription>
                                  {t("memberList.removeDialog.description", {
                                    name,
                                  })}
                                </DialogDescription>
                              </DialogHeader>
                              <DialogFooter>
                                <Button
                                  variant="destructive"
                                  onClick={() => handleRemove(memberId, name)}
                                  disabled={isBusy}
                                >
                                  {isBusy
                                    ? t(
                                        "memberList.removeDialog.confirmPending"
                                      )
                                    : t("memberList.removeDialog.confirm")}
                                </Button>
                              </DialogFooter>
                            </DialogContent>
                          </Dialog>
                        )}
                      </TableCell>
                    )}
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </div>
      )}

      {/* A request in flight keeps the dialog open until it settles. */}
      <AlertDialog
        open={transferOpen}
        onOpenChange={(next) => {
          if (!isTransferring) setTransferOpen(next);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {t("memberList.transferDialog.title", {
                name: transferTarget?.name ?? "",
              })}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {t("memberList.transferDialog.description", {
                name: transferTarget?.name ?? "",
              })}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isTransferring}>
              {t("memberList.transferDialog.cancel")}
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={handleTransfer}
              disabled={isTransferring}
              aria-busy={isTransferring}
            >
              {isTransferring
                ? t("memberList.transferDialog.confirmPending")
                : t("memberList.transferDialog.confirm")}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client";

/**
 * Invite member form — owner/admin only. Client-side required-field
 * checks are handled by the `email` input; server-side validation
 * errors from the action are surfaced inline.
 */

import { useState, useTransition, type FormEvent } from "react";
import { useTranslations } from "next-intl";
import { toast } from "sonner";

import { inviteMember } from "@/actions/team";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";

export function InviteMemberForm() {
  const t = useTranslations("team-settings");
  // The labels SelectValue shows; Base UI renders the raw value without them.
  const roleItems = [
    { value: "member", label: t("roles.member") },
    { value: "admin", label: t("roles.admin") },
  ];
  const [isPending, startTransition] = useTransition();
  const [email, setEmail] = useState("");
  const [role, setRole] = useState<"admin" | "member">("member");
  const [error, setError] = useState<string | null>(null);

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);

    startTransition(async () => {
      const result = await inviteMember({ email, role });
      if (!result.success) {
        setError(result.error);
        return;
      }
      toast.success(t("inviteForm.inviteSent", { email }));
      setEmail("");
      setRole("member");
    });
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>{t("inviteForm.title")}</CardTitle>
        <CardDescription>{t("inviteForm.description")}</CardDescription>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="email">{t("inviteForm.emailLabel")}</Label>
            <Input
              id="email"
              type="email"
              placeholder={t("inviteForm.emailPlaceholder")}
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              disabled={isPending}
              required
            />
            {error && <p className="text-sm text-destructive">{error}</p>}
          </div>

          <div className="space-y-2">
            <Label htmlFor="role">{t("inviteForm.roleLabel")}</Label>
            <Select
              value={role}
              items={roleItems}
              onValueChange={(value) =>
                value && setRole(value as "admin" | "member")
              }
              disabled={isPending}
            >
              <SelectTrigger id="role">
                <SelectValue placeholder={t("inviteForm.rolePlaceholder")} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="member">{t("roles.member")}</SelectItem>
                <SelectItem value="admin">{t("roles.admin")}</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <Button type="submit" disabled={isPending}>
            {isPending ? t("inviteForm.submitPending") : t("inviteForm.submit")}
          </Button>
        </form>
      </CardContent>
    </Card>
  );
}

"use client";

/**
 * Pending invitations — table of outstanding workspace invitations
 * with a confirmed cancel action. Rendered for owner/admin only.
 */

import { useState, useTransition } from "react";
import { useFormatter, useTranslations } from "next-intl";
import { toast } from "sonner";

import type { OrgInvitation } from "@intelligo-dev/auth";

import { cancelInvitation } from "@/actions/team";
import { RoleBadge } from "./role-badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

interface PendingInvitationsProps {
  invitations: OrgInvitation[];
}

export function PendingInvitations({ invitations }: PendingInvitationsProps) {
  const t = useTranslations("team-settings");
  const format = useFormatter();
  const [isPending, startTransition] = useTransition();
  const [busyId, setBusyId] = useState<string | null>(null);
  // The target outlives `cancelOpen` so the email stays while the dialog exits.
  const [cancelTarget, setCancelTarget] = useState<{
    id: string;
    email: string;
  } | null>(null);
  const [cancelOpen, setCancelOpen] = useState(false);
  const isCanceling =
    isPending && cancelTarget !== null && busyId === cancelTarget.id;

  function handleCancel() {
    if (!cancelTarget) return;
    const { id } = cancelTarget;
    setBusyId(id);
    startTransition(async () => {
      const result = await cancelInvitation(id);
      if (!result.success) {
        toast.error(result.error);
      } else {
        toast.success(t("pendingInvitations.canceled"));
      }
      setBusyId(null);
      setCancelOpen(false);
    });
  }

  return (
    <div>
      <h2 className="mb-3 text-sm font-semibold">
        {t("pendingInvitations.heading", { count: invitations.length })}
      </h2>

      {invitations.length === 0 ? (
        <div className="rounded-md border border-dashed px-6 py-10 text-center">
          <p className="text-sm font-medium">{t("pendingInvitations.empty")}</p>
          <p className="mt-1 text-sm text-muted-foreground">
            {t("pendingInvitations.emptyHint")}
          </p>
        </div>
      ) : (
        <div className="rounded-md border">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>{t("pendingInvitations.columns.email")}</TableHead>
                <TableHead>{t("pendingInvitations.columns.role")}</TableHead>
                <TableHead className="hidden sm:table-cell">
                  {t("pendingInvitations.columns.status")}
                </TableHead>
                <TableHead className="hidden md:table-cell">
                  {t("pendingInvitations.columns.expires")}
                </TableHead>
                <TableHead className="text-right">
                  {t("pendingInvitations.columns.actions")}
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {invitations.map((invitation) => {
                const isBusy = isPending && busyId === invitation.id;
                const isExpired = new Date(invitation.expiresAt) < new Date();

                return (
                  <TableRow key={invitation.id}>
                    <TableCell className="font-medium">
                      {invitation.email}
                    </TableCell>
                    <TableCell>
                      <RoleBadge role={invitation.role} />
                    </TableCell>
                    <TableCell className="hidden sm:table-cell">
                      {isExpired ? (
                        <span className="text-sm text-destructive">
                          {t("pendingInvitations.expired")}
                        </span>
                      ) : (
                        <span className="text-sm text-muted-foreground">
                          {t("pendingInvitations.pending")}
                        </span>
                      )}
                    </TableCell>
                    <TableCell className="hidden md:table-cell">
                      {format.dateTime(new Date(invitation.expiresAt), {
                        dateStyle: "medium",
                      })}
                    </TableCell>
                    <TableCell className="text-right">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => {
                          setCancelTarget({
                            id: invitation.id,
                            email: invitation.email,
                          });
                          setCancelOpen(true);
                        }}
                        disabled={isBusy}
                      >
                        {isBusy
                          ? t("pendingInvitations.cancelPending")
                          : t("pendingInvitations.cancel")}
                      </Button>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </div>
      )}

      {/* A request in flight keeps the dialog open until it settles. */}
      <AlertDialog
        open={cancelOpen}
        onOpenChange={(next) => {
          if (!isCanceling) setCancelOpen(next);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {t("pendingInvitations.cancelDialog.title")}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {t("pendingInvitations.cancelDialog.description", {
                email: cancelTarget?.email ?? "",
              })}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={isCanceling}>
              {t("pendingInvitations.cancelDialog.keep")}
            </AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              onClick={handleCancel}
              disabled={isCanceling}
              aria-busy={isCanceling}
            >
              {isCanceling
                ? t("pendingInvitations.cancelPending")
                : t("pendingInvitations.cancelDialog.confirm")}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client";

import { useTranslations } from "next-intl";

import { Badge } from "@/components/ui/badge";

/**
 * A role is a label, not a status: the badges stay quiet and differ by
 * their text rather than by colour.
 */
const VARIANT_BY_ROLE: Record<string, "default" | "secondary" | "outline"> = {
  owner: "secondary",
  admin: "outline",
  member: "outline",
};

interface RoleBadgeProps {
  role: string;
}

export function RoleBadge({ role }: RoleBadgeProps) {
  const t = useTranslations("team-settings");

  return (
    <Badge variant={VARIANT_BY_ROLE[role] ?? "outline"} className="capitalize">
      {t.has(`roles.${role}`) ? t(`roles.${role}`) : role}
    </Badge>
  );
}

"use client";

/**
 * Leave workspace — every role can leave. The sole owner cannot: the
 * service refuses and the message says to make someone else an owner
 * first.
 */

import { useState, useTransition } from "react";
import { useTranslations } from "next-intl";
import { toast } from "sonner";

import { useRouter } from "@/i18n/navigation";
import { leaveWorkspace } from "@/actions/team";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

interface LeaveWorkspaceProps {
  workspaceName: string;
}

export function LeaveWorkspace({ workspaceName }: LeaveWorkspaceProps) {
  const t = useTranslations("team-settings");
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [open, setOpen] = useState(false);

  function handleLeave() {
    startTransition(async () => {
      const result = await leaveWorkspace();
      if (!result.success) {
        toast.error(result.error);
        setOpen(false);
        return;
      }
      toast.success(t("leave.left", { workspace: workspaceName }));
      router.push("/dashboard");
      router.refresh();
    });
  }

  return (
    <Card className="border-destructive/30">
      <CardHeader>
        <CardTitle>{t("leave.title")}</CardTitle>
        <CardDescription>
          {t("leave.description", { workspace: workspaceName })}
        </CardDescription>
      </CardHeader>
      <CardContent>
        {/* A request in flight keeps the dialog open until it settles. */}
        <AlertDialog
          open={open}
          onOpenChange={(next) => {
            if (!isPending) setOpen(next);
          }}
        >
          <AlertDialogTrigger render={<Button variant="destructive" />}>
            {t("leave.trigger")}
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>
                {t("leave.dialogTitle", { workspace: workspaceName })}
              </AlertDialogTitle>
              <AlertDialogDescription>
                {t("leave.dialogDescription")}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel disabled={isPending}>
                {t("leave.cancel")}
              </AlertDialogCancel>
              <AlertDialogAction
                variant="destructive"
                onClick={handleLeave}
                disabled={isPending}
                aria-busy={isPending}
              >
                {isPending ? t("leave.confirmPending") : t("leave.confirm")}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </CardContent>
    </Card>
  );
}

"use server";

/**
 * Team settings server actions — thin transport over the bound team
 * service (`@/lib/team`): parse input with the schemas from
 * `@intelligo-dev/auth`, call the service, map any `TeamServiceError` to a
 * friendly message, and revalidate the page. No business rules here —
 * those live in the service.
 */

import { revalidatePath } from "next/cache";
import { getTranslations } from "next-intl/server";

import {
  inviteMemberSchema,
  isTeamServiceError,
  updateRoleSchema,
  type InviteMemberInput,
  type UpdateRoleInput,
} from "@intelligo-dev/auth";
import type { ActionResult } from "@intelligo-dev/next";

import { team } from "@/lib/team";

export type TeamActionResult<T = undefined> = ActionResult<T>;

type Translator = Awaited<ReturnType<typeof getTranslations<"team-settings">>>;

function friendlyMessage(
  t: Translator,
  limit: number | undefined
): Partial<Record<string, string>> {
  return {
    member_limit_reached:
      limit === undefined
        ? t("errors.memberLimitReached")
        : t("errors.memberLimitReachedCount", { limit }),
    invitation_not_found: t("errors.invitationNotFound"),
    sole_owner: t("errors.soleOwner"),
    forbidden: t("errors.forbidden"),
    invalid_input: t("errors.invalidInput"),
    accept_verification_failed: t("errors.acceptVerificationFailed"),
    provider_error: t("errors.providerError"),
  };
}

function friendlyError(error: unknown, t: Translator): string {
  // Unknown errors deliberately map to the generic key — a raw
  // `Error#message` can carry internals (SQL, hostnames) to the UI.
  if (isTeamServiceError(error)) {
    return (
      friendlyMessage(t, error.meta?.limit)[error.code] ??
      t("errors.somethingWentWrong")
    );
  }
  return t("errors.somethingWentWrong");
}

export async function inviteMember(
  input: InviteMemberInput
): Promise<TeamActionResult> {
  const t = await getTranslations("team-settings");
  const parsed = inviteMemberSchema.safeParse(input);
  if (!parsed.success) {
    return {
      success: false,
      error: parsed.error.issues[0]?.message ?? t("errors.invalidInput"),
    };
  }

  try {
    await team.inviteMember(parsed.data);
    revalidatePath("/settings/team");
    return { success: true, data: undefined };
  } catch (error) {
    return { success: false, error: friendlyError(error, t) };
  }
}

